import{_ as t,o as a,c as s,a5 as o}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"PS001-不打开ps将psd文件导出为jpg图片","日期":"2026-04-11T00:00:00.000Z","修改日期":"2026-04-11T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["Bat批处理"],"标签":["psd文件转jpg","不打开photoshop","不打开ps","批量psd文件转jpg","批量psd转jpg"]},"headers":[],"relativePath":"md/Bat批处理/PS001-不打开ps将psd文件导出为jpg图片.md","filePath":"md/Bat批处理/PS001-不打开ps将psd文件导出为jpg图片.md"}'),r={name:"md/Bat批处理/PS001-不打开ps将psd文件导出为jpg图片.md"};function n(e,p,g,d,l,i){return a(),s("div",null,[...p[0]||(p[0]=[o('<h2 id="ps001-不打开ps将psd文件导出为jpg图片" tabindex="-1">PS001-不打开ps将psd文件导出为jpg图片 <a class="header-anchor" href="#ps001-不打开ps将psd文件导出为jpg图片" aria-label="Permalink to &quot;PS001-不打开ps将psd文件导出为jpg图片&quot;">​</a></h2><p>这个批处理程序的主要功能是将指定文件夹下的所有 PSD 文件转换为jpg 图片。</p><p>程序会查找文件夹下的所有 PSD 文件，将 PSD 文件转换为 JPG 图片，转换后的图片大小为 1920x1920 像素/分辨率**（如果自己看得懂bat脚本可以自行修改分辨率）。**</p><p>转换后的 JPG 图片将存储在与 PSD 文件相同的目录下，文件名与 PSD 文件名相同，只是扩展名为 .jpg。</p><p><strong>需要注意的是，程序依赖于 ImageMagick 工具，因此在运行程序之前，需要先安装 ImageMagick 并配置环境变量。</strong></p><p><strong>拿到文件后先按照说明安装此工具：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250129142732173813205288480.png" alt=""></p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多psd文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有psd文件。</p><p>【操作方法】：打开批处理程序后，输入A文件夹路径，运行后会将所有psd转为图片，保存在原psd所在文件夹内，支持子文件夹穿透。</p><h3 id="📑-bat程序下一步执行方法" tabindex="-1">📑 bat程序下一步执行方法 <a class="header-anchor" href="#📑-bat程序下一步执行方法" aria-label="Permalink to &quot;📑 bat程序下一步执行方法&quot;">​</a></h3><p>**▶ **使用时，<strong>键盘回车键（就是键盘上的 ENTER 键）</strong>“回车确认”是执行下一步的方法 ，</p><p>比如将路径复制到程序中后，回车键确认执行下一步，每一步输入后，回车键确认即可向下执行。</p><p><strong>▶ 注意：请先测试备份原文件再批量使用，以免造成不可逆损失！！！</strong></p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250128114319173803579959658.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>：建议win7及以上64位win操作系统，mac系统需要定制。</p><p><strong>注意事项：bat程序原理上是支持</strong>win32位系统的，但不能完全确定。</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：程序不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><p>📑 本工具下载地址</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1162.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1162.html</a></p>',21)])])}const _=t(r,[["render",n]]);export{c as __pageData,_ as default};
